{
  "schema_version": 1,
  "mechanism_id": "behavior_directed_code_assignment_cross_entropy",
  "version": "3.0.0",
  "title": "Behavior-directed code-assignment cross-entropy",
  "equation": "For each valid directed pair (b), define q_k(x_b; E) = exp(-||x_b - e_k||^2 / tau) / sum_j exp(-||x_b - e_j||^2 / tau). The loss is L = -sum_b m_b sum_k q_k(t_b; E) log(q_k(s_b; E) + epsilon) / (sum_b m_b + epsilon).",
  "symbols": {
    "L": "Mean directed assignment cross-entropy over valid source-target behavior pairs.",
    "b": "Index of a source-target pair in the batch.",
    "m_b": "Binary validity mask for pair b.",
    "s_b": "Source item representation for pair b.",
    "t_b": "Behavior-associated target item representation for pair b.",
    "E": "Rows e_k of the codebook level being regularized.",
    "e_k": "Codebook vector at row k.",
    "k": "Codebook row index, from 1 to C.",
    "C": "Number of codebook rows.",
    "D": "Representation and codebook-vector dimension.",
    "q_k(x; E)": "Soft assignment probability of representation x to codebook row k.",
    "tau": "Positive soft-assignment temperature.",
    "epsilon": "Positive numerical stabilizer for the logarithm and valid-pair denominator."
  },
  "parameters": {
    "tau": 0.5,
    "epsilon": 1e-8
  },
  "target_paths": [
    "encoder",
    "codebook",
    "hard_sid_export"
  ],
  "hypotheses": [
    "Behavior-directed targets will shape codebook geometry through gradients on the codebook rows, so the host's encoder-gradient overwrite will not erase the entire mechanism.",
    "The asymmetric source-to-target assignment objective will preserve behavior-relevant directed structure better than an ER-only objective; select it only if matched downstream recall@10 improves over r8_control without violating the existing ER gate.",
    "Use a fixed auxiliary weight of 0.01 for the initial matched comparison; retain the mechanism only if the independent checks pass, exported SIDs differ from control, and the cold-run downstream criterion is met."
  ],
  "expected_failure_modes": [
    "Zero or non-finite codebook gradients indicate a broken assignment or loss path; codebook rows and exported SIDs may then remain identical to control.",
    "Collapsed code usage, increased code-frequency concentration, or degraded downstream recall indicate that behavior supervision has over-organized the codebook.",
    "A symmetric loss implementation would fail the source-target exchange invariant and would no longer implement the directed mechanism.",
    "A detached assignment or stop-gradient through the codebook assignment probabilities would prevent the claimed codebook organization.",
    "A loss that does not become zero when all pairs are masked indicates incorrect mask handling or normalization."
  ],
  "tests": [
    {
      "id": "forward_finite",
      "kind": "numeric",
      "statement": "On the supplied synthetic case with at least one valid pair, the loss is finite."
    },
    {
      "id": "codebook_permutation",
      "kind": "metamorphic",
      "statement": "Permuting codebook rows leaves the scalar loss unchanged within tolerance."
    },
    {
      "id": "directed_pair",
      "kind": "metamorphic",
      "statement": "Exchanging source and target changes the scalar loss by more than tolerance on the supplied non-degenerate synthetic case."
    },
    {
      "id": "all_pairs_masked",
      "kind": "metamorphic",
      "statement": "Masking every pair yields exactly zero loss, up to the declared tolerance."
    },
    {
      "id": "gradient_paths",
      "kind": "gradient",
      "statement": "With a valid non-degenerate case, gradients with respect to source, target, and codebook are finite and nonzero."
    },
    {
      "id": "host_integration",
      "kind": "integration",
      "statement": "On the host mini case, confirm the auxiliary term changes the codebook gradient after host assembly; do not rely on an encoder-only gradient surviving the host overwrite. In a matched cold run, compare exported SIDs and downstream recall@10 with r8_control; require the existing ER gate and improved recall@10 to retain the mechanism."
    }
  ],
  "judges": [
    "contract_audit",
    "forward_oracle",
    "derivative_evidence",
    "property_checks",
    "integration_on_off"
  ],
  "forbidden_substitutions": [
    {
      "id": "symmetric_assignment_objective",
      "pattern": "L\\s*=\\s*-?\\s*.*(?:q_k\\(s_b;\\s*E\\).*log\\(q_k\\(t_b;\\s*E\\)|q_k\\(t_b;\\s*E\\).*log\\(q_k\\(s_b;\\s*E\\)).*\\+.*(?:q_k\\(t_b;\\s*E\\).*log\\(q_k\\(s_b;\\s*E\\)|q_k\\(s_b;\\s*E\\).*log\\(q_k\\(t_b;\\s*E\\))",
      "reason": "Symmetrizing the directed cross-entropy changes the mechanism and can erase the required source-target exchange sensitivity."
    },
    {
      "id": "detached_codebook_assignments",
      "pattern": "(?:stop_gradient|detach)\\s*\\(\\s*q_k\\s*\\(",
      "reason": "Detaching codebook assignment probabilities blocks the claimed codebook gradient and repeats the encoder-only failure under the host gradient overwrite."
    },
    {
      "id": "encoder_only_gradient_route",
      "pattern": "(?:stop_gradient|detach)\\s*\\(\\s*E\\s*\\)",
      "reason": "Blocking gradients to the codebook prevents this mechanism from moving the representation organization that the host leaves trainable."
    }
  ],
  "invariants": [
    {
      "id": "row_permutation",
      "transform": "permute_codebook",
      "expect": "unchanged",
      "tolerance": 1e-6
    },
    {
      "id": "source_target_exchange",
      "transform": "swap_source_target",
      "expect": "changed",
      "tolerance": 1e-6
    },
    {
      "id": "all_pairs_masked",
      "transform": "mask_all",
      "expect": "zero",
      "tolerance": 1e-8
    }
  ],
  "gradient_targets": {
    "source": "finite",
    "target": "finite",
    "codebook": "finite"
  },
  "inputs": {
    "source": {
      "shape": [4, 3],
      "seed": 11
    },
    "target": {
      "shape": [4, 3],
      "seed": 12
    },
    "codebook": {
      "shape": [5, 3],
      "seed": 13
    },
    "mask": {
      "seed": 17,
      "valid_fraction": 0.75
    }
  },
  "activation": {
    "kind": "term",
    "weight": 0.01
  },
  "differentiation": {
    "occupancy_preservation": "This objective contains no explicit uniform-occupancy penalty: it preserves occupancy only insofar as the directed behavior pairs support diverse assignments. Reject it if code usage becomes more concentrated than control or downstream recall declines.",
    "vs_r8": [
      {
        "lane": "r8_01_directed_l1_transition_nce",
        "why": "Uses directed soft item-to-code assignment cross-entropy, not NCE over hard L1 code transitions; it directly differentiates through codebook rows."
      },
      {
        "lane": "r8_02_l1_next_item_prediction",
        "why": "Does not train an L1 next-item semantic prediction head; the behavior target acts on assignments to the existing codebook."
      },
      {
        "lane": "r8_03_successor_profile_js",
        "why": "Does not match successor-profile distributions with JS divergence; it trains a directed conditional assignment objective."
      },
      {
        "lane": "r8_04_behavior_conditioned_ot",
        "why": "Does not solve an entropic OT quantization or assignment problem; its normalized per-item soft assignments are directly optimized against behavior-paired targets."
      },
      {
        "lane": "r8_05_three_level_distillation",
        "why": "Does not distill a teacher across three levels; it applies the same directed objective to the selected codebook level."
      },
      {
        "lane": "r8_06_train_graph_diffusion",
        "why": "Does not preserve graph diffusion distances; it uses observed directed source-target behavior pairs."
      },
      {
        "lane": "r8_07_hyperbolic_gyro",
        "why": "Uses Euclidean soft code assignments rather than hyperbolic gyro-translation."
      },
      {
        "lane": "r8_08_hyperbolic_frechet",
        "why": "Does not form hyperbolic Frechet successor barycentres; target behavior is represented by its soft code assignment."
      },
      {
        "lane": "r8_09_hyperbolic_branching",
        "why": "Does not impose a hyperbolic radial hierarchy or branching structure."
      },
      {
        "lane": "r8_10_hyperbolic_gw",
        "why": "Does not optimize a hyperbolic graph-code Gromov-Wasserstein objective."
      },
      {
        "lane": "r8_control",
        "why": "Unlike the untouched host control, this adds a behavior-conditioned directed loss with a differentiable path into codebook rows."
      }
    ],
    "vs_reference_arm": "Unlike the previously measured encoder-only auxiliary arms, this objective differentiates through codebook-dependent soft assignments. The host overwrites encoder gradients but leaves codebook gradients untouched, so the codebook path can alter learned representations and, after re-export, hard L1/L2/L3 SIDs. Hard SID assignment itself is discrete and receives no direct gradient; changes are indirect through updated encoder/codebook parameters."
  },
  "provenance": {
    "authored_by": "researcher",
    "authored_at": "2026-10-21T00:00:00Z"
  }
}
